// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(address actor, uint256 ts) public {
        vm.assume(actor != address(0));
        ts = bound(ts, 1, type(uint48).max);
        vm.warp(ts);
        vm.deal(actor, 20 ether);

        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        // General rule: a second call in the SAME timestamp must revert.
        assertTrue(!ok2);
    }
}
